-- Client access: each employee can see the clients they work on
insert into public.employee_clients (employee_id, client_id)
select distinct e, client_id from (
  select default_assignee_id as e, client_id from public.task_templates where default_assignee_id is not null
  union select default_reviewer_id, client_id from public.task_templates where default_reviewer_id is not null
) s on conflict do nothing;

